      SUBROUTINE ADVANC(I)CC     CALCULATE THE COORDINATE ROTATION MATRIX AND VECTOR SPANNINGC     THE BEAM LINE SINCE THE LAST UPDATEC     USED FOR MISALIGNMENT CALCULATIONS AND FLOOR COORDINATE LAYOUTSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OCP.CIN'CC     LOCAL VARIABLESC      INTEGER  I, J, K, L      REAL  O1(3,3), S, S1CC------------------------------------------------------------      IF (I .LT. 0 .OR. I .GT. 4) THEN        WRITE (NOUT,9001) I 9001   FORMAT (' *** ERROR ***, I = ',I2,'IN ADVANC')        FLUSHL = .TRUE.        GO TO 20      ENDIF      IF (.NOT. OMTX) GO TO 15      IF (.NOT. OCP(I)) GO TO 10CC     MULTIPLY COORDINATE ROTATION OF ELEMENT TIMES ACCUMULATEDC     COORDINATE ROTATIONC      DO 2 J = 1, 3      DO 2 K = 1, 3      S1 = 0.0      DO 1 L = 1, 3      S1 = S1 + O(1,J,L)*O(I,L,K)    1 CONTINUE      O1(J,K)  =  S1    2 CONTINUEC      DO 5 J = 1, 3      S = 0.0      DO 4 K = 1, 3      S = S + O(I,K,J)*X0(1,K)    4 CONTINUE      X0(I,J) = X0(I,J) + S    5 CONTINUEC      DO 8 J = 1, 3      DO 7 K = 1, 3      O(I,J,K) = O1(J,K)    7 CONTINUE    8 CONTINUE      GO TO 20CC     ACCUMULATED COORDINATE ROTATION IS COORDINATE ROTATION OF LASTC     ELEMENTC   10 DO 11 J = 1, 3      X0(I,J) = X0(1,J)      DO 11 K = 1, 3      O(I,J,K) = O(1,J,K)   11 CONTINUE   15 OCP(I) = .TRUE.C   20 RETURN      END